import json, sys, collections
INV = '/private/tmp/claude-501/-Users-kevingalligan-devel-framejob/9cfd7405-83ec-4caa-905f-7b97a20f2cc9/scratchpad/inventory'
pool = json.load(open(INV + '/work-editing/pool.json'))
groups = collections.defaultdict(list)
for id, r in pool.items():
    k = next((p for p in r['assign'] if p.startswith('editing/')), None) or (r['assign'][0] if r['assign'] else 'NONE')
    groups[k].append(r)


def fmt(r):
    s = f"[{r['id']}] {r['name']} ({r.get('area')}) :: {r.get('what')}"
    if r.get('ui'):
        s += ' | UI: ' + '; '.join(r['ui'])
    if r.get('mcp'):
        s += ' | MCP: ' + ','.join(r['mcp'])
    rq = [x for x in (r.get('requires') or []) if x != 'none']
    if rq:
        s += ' | REQ: ' + '; '.join(rq)
    if r.get('details'):
        s += ' | D: ' + ' / '.join(r['details'])
    s += ' | @' + str(r.get('evidence'))
    return s


want = sys.argv[1:]
if not want:
    for k, v in sorted(groups.items()):
        print(k, len(v), sum(len(fmt(r)) for r in v))
else:
    for k in want:
        print('=====', k)
        for r in groups[k]:
            print(fmt(r))

