import json, glob, collections, sys
INV = '/private/tmp/claude-501/-Users-kevingalligan-devel-framejob/9cfd7405-83ec-4caa-905f-7b97a20f2cc9/scratchpad/inventory'
pool = json.load(open(INV + '/work-editing/pool.json'))
kw = {r['id']: r for r in json.load(open(INV + '/work-editing/kw.json'))}
a = json.load(open(INV + '/tax/assign.json'))
n2p = collections.defaultdict(list)
for p, ns in a.items():
    for n in ns:
        n2p[n].append(p)
recs = {}
for f in sorted(glob.glob(INV + '/raw/*.json')):
    for r in json.load(open(f)):
        recs[r['id']] = r


def fmt(r):
    s = f"[{r['id']}] {r['name']} ({r.get('area')}) -> {','.join(n2p.get(r['name'].strip().lower(), []))} :: {r.get('what')}"
    if r.get('ui'):
        s += ' | UI: ' + '; '.join(r['ui'])
    if r.get('mcp'):
        s += ' | MCP: ' + ','.join(r['mcp'])
    if r.get('details'):
        s += ' | D: ' + ' / '.join(r['details'])
    s += ' | @' + str(r.get('evidence'))
    return s[:700]


print('## guide-editing not in pool')
seen = set()
for id, r in recs.items():
    if id.startswith('guide-editing-') and id not in pool:
        print(fmt(r))
        seen.add(id)
print('## keyword hits')
for id, r in kw.items():
    if id not in seen:
        print(fmt(r))

