rejected = []
for rid in sorted(reviewed):
    if rid in claimed:
        continue
    r = recs[rid]
    sec = OVERRIDE.get(rid)
    if not sec:
        area = r.get('area')
        if area in AREA:
            sec = AREA[area]
        else:
            pg = [p for p in (pool.get(rid) or {}).get('assign', []) if not p.startswith('editing/')]
            sec = pg[0].split('/')[0] if pg else None
    if not sec or sec == 'editing' or sec not in sections:
        print('NO SECTION', rid, r.get('area'), r['name'], (pool.get(rid) or {}).get('assign'))
        ok = False
        continue
    rejected.append({'raw_id': rid, 'reason': 'belongs to ' + sec})

out = {'section': 'editing', 'features': FEATURES, 'rejected': rejected}
os.makedirs(INV + '/features', exist_ok=True)
if ok:
    json.dump(out, open(INV + '/features/editing.json', 'w'), ensure_ascii=False, indent=1)
print('features', len(FEATURES), 'raw claimed', len(claimed), 'rejected', len(rejected), 'reviewed', len(reviewed))
print(collections.Counter(x['reason'] for x in rejected).most_common())
print('per page', collections.Counter(f['page'] for f in FEATURES))
print('empty pages', sorted(mine - {f['page'] for f in FEATURES}))
print('editing-area rejected')
for x in rejected:
    if recs[x['raw_id']].get('area') == 'editing' or x['raw_id'].startswith('guide-editing-'):
        print(' ', x['raw_id'], recs[x['raw_id']]['name'], '->', x['reason'])

